MagickBooleanType WritePSDImageChannels(const PSDInfo *psd_info,
                                        const ImageInfo *image_info,
                                        Image *image, Image *next_image,
                                        MagickBooleanType separate,
                                        ExceptionInfo *exception) {
  size_t number_channels;
  ssize_t y;
  MagickBooleanType status;
  Quantum *pixels;

  status = MagickTrue;

  if (next_image != (Image *) NULL)
    (void) CloneImageAttributes(image, next_image);

  number_channels = 1;
  if (image->alpha_trait)
    number_channels++;

  pixels = (Quantum *) AcquireQuantumMemory(image->columns, sizeof(*pixels));
  if (pixels == (Quantum *) NULL)
    return MagickFalse;

  for (y = 0; y < (ssize_t) image->rows; y++) {
    for (ssize_t x = 0; x < (ssize_t) image->columns; x++) {
      pixels[x] = GetPixelRed(image, image->pixels[image->columns * y + x]);
    }

    status = WritePSDPixelData(psd_info, image_info, image, pixels, y,
                               number_channels, exception);
    if (status == MagickFalse)
      break;
  }

  pixels = (Quantum *) RelinquishMagickMemory(pixels);
  return status;
}

