MagickBooleanType WritePSDImage(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickBooleanType separate, ExceptionInfo *exception)
{
    MagickBooleanType status = MagickFalse;
    size_t number_pixels;
    Quantum *pixels = NULL;
    ssize_t y;
    CompressionType compression = next_image->compression;
    ColorSpace color_space = next_image->colorspace;

    /* Initialize progress tracking */
    (void) AcquireUniquePath("psd_temp", psd_info->temporary_directory, psd_info->temporary_file, sizeof(psd_info->temporary_file));

    number_pixels = image->columns * image->rows;
    pixels = (Quantum *) AcquireQuantumMemory(number_pixels, sizeof(Quantum));
    if (pixels == (Quantum *) NULL)
        goto cleanup;

    if (compression == RLECompression)
    {
        /* Apply Packbits compression logic */
        if (WriteRLECompressedData(psd_info, image, pixels, exception) != MagickTrue)
            goto cleanup;
    }

    switch (color_space)
    {
        case GRAYColorspace:
            if (WriteGrayscaleChannelData(psd_info, image, pixels, exception) != MagickTrue)
                goto cleanup;
            break;

        case IndexColorspace:
            if (WriteIndexChannelData(psd_info, image, pixels, exception) != MagickTrue)
                goto cleanup;
            break;

        case RGBColorspace:
            if (WriteRGBChannelData(psd_info, image, pixels, exception) != MagickTrue)
                goto cleanup;
            break;

        default:
            break;
    }

    if (separate && WriteAlphaChannel(psd_info, image, pixels, exception) != MagickTrue)
        goto cleanup;

    /* Report progress */
    SyncImageProgress(image, SaveImagesTag, 1, 1);

    status = MagickTrue;

cleanup:
    if (pixels != (Quantum *) NULL)
        pixels = RelinquishQuantumMemory(pixels);

    return status;
}
